def grade(reply, order_id, max_words):
    lines = [l.strip() for l in reply.splitlines() if l.strip()]
    last = lines[-1] if lines else ''
    return {
        'mentions_order': order_id in reply,
        'length_ok': len(reply.split()) <= max_words,
        'no_placeholder': not any(p in reply for p in ('[NAME]', '{{', 'TODO')),
        'polite_close': last.startswith(('Thanks', 'Best')),
    }

